//! `scf` generated by `mlirformat tblgen` (`scf.gen.rs`) against the `mlir-opt` 22.1.8 fixtures.
//! One test crate per dialect so cargo builds them in parallel; `cargo test --features gen-tests`.

#[path = "../common/mod.rs"]
mod common;
#[path = "scf.gen.rs"]
mod scf;

#[test]
fn scf_matches_mlir_opt() {
    let mut opt = mlirformat::MlirOpt::new();
    opt.register::<scf::Scf>();
    common::Fixtures::check_dialect(&opt, "scf");
}
